public boolean transfer(AccountRow row, long debit, long expectedVersion) {
  // Read phase already captured expectedVersion. Validate at commit.
  String sql = "UPDATE accounts SET balance = balance - ?, version = version + 1 "
             + "WHERE id = ? AND version = ? AND balance >= ?";
  int updated;
  try (var ps = conn.prepareStatement(sql)) {
    ps.setLong(1, debit);
    ps.setLong(2, row.id());
    ps.setLong(3, expectedVersion);
    ps.setLong(4, debit);
    updated = ps.executeUpdate();
  }
  // updated == 0 means conflict or insufficient funds: abort, back off, retry.
  // WHY this shape: no lock held during user think time; conflict cost
  // is a retry, not a queue. Trade-off: hot keys thrash — switch to
  // pessimistic SELECT ... FOR UPDATE when abort rate exceeds ~5-10%.
  return updated == 1;
}
